15	/**
16	 * Handler that bridges {@see AppCountryISOsParam} into a
17	 * {@see \Application\API\Parameters\Handlers\BaseParamsHandlerContainer}.
18	 *
19	 * Provides type-narrowed overrides for {@see register()} and {@see getParam()}
20	 * so consumers receive a typed `AppCountryISOsParam` without casting.
21	 *
22	 * @package Countries
23	 * @subpackage API
24	 * @see AppCountryISOsParam
25	 */
26	class AppCountryISOsHandler extends BaseParamHandler
27	{
28	    /**
29	     * Resolves the list of countries from the registered parameter.
30	     *
31	     * Returns `null` when the parameter has no value so that the
32	     * {@see \Application\API\Parameters\Handlers\BaseParamsHandlerContainer}
33	     * "first non-null wins" iteration can fall through to the next handler.
34	     *
35	     * @return Application_Countries_Country[]|null
36	     */
37	    protected function resolveValueFromSubject(): ?array
38	    {
39	        $param = $this->getParam();
40	
41	        if($param === null || $param->getValue() === null) {
42	            return null;
43	        }
44	
45	        return $param->getCountries();
46	    }
47	
48	    /**
49	     * Registers the parameter and returns it type-narrowed.
50	     *
51	     * @return AppCountryISOsParam
